// Parser do email do Gather Town
// Recebe item do Gmail Trigger e extrai metadados estruturados.

const out = [];

for (const item of $input.all()) {
  const msg = item.json;

  const headers = msg.headers || msg.payload?.headers || {};
  const getHeader = (name) => {
    if (Array.isArray(headers)) {
      const h = headers.find((x) => x.name?.toLowerCase() === name.toLowerCase());
      return h?.value || '';
    }
    return headers[name] || headers[name.toLowerCase()] || '';
  };

  const subject = msg.subject || getHeader('Subject') || '';
  const fromAddress = msg.from?.value?.[0]?.address || msg.from || getHeader('From') || '';
  const messageId = msg.id || msg.messageId || getHeader('Message-ID') || '';
  const threadId = msg.threadId || '';

  const html = msg.html || msg.payload?.html || '';
  const textRaw = msg.text || msg.textPlain || msg.snippet || '';
  const text = (textRaw || stripHtml(html)).replace(/\r/g, '').trim();

  function stripHtml(s) {
    if (!s) return '';
    return s
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|h[1-6])>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  // Título: subject costuma vir como "Gather meeting summary: <título>" ou similar
  let meetingTitle = subject
    .replace(/^(re:|fwd:)\s*/i, '')
    .replace(/^.*?(meeting|summary)[^:]*:\s*/i, '')
    .trim();
  if (!meetingTitle) meetingTitle = subject;

  // Data da reunião: tenta achar no corpo, senão usa data do email
  const dateLine = text.match(/\b(?:date|when|data)[:\-]?\s*(.+)/i)?.[1];
  let meetingDate = null;
  if (dateLine) {
    const d = new Date(dateLine);
    if (!isNaN(d)) meetingDate = d.toISOString();
  }
  if (!meetingDate) {
    const internalDate = msg.internalDate ? Number(msg.internalDate) : null;
    if (internalDate) meetingDate = new Date(internalDate).toISOString();
    else if (getHeader('Date')) {
      const d = new Date(getHeader('Date'));
      if (!isNaN(d)) meetingDate = d.toISOString();
    }
  }

  // Duração
  const durMatch = text.match(/(\d+)\s*(min|minute|minuto)/i);
  const durationMin = durMatch ? parseInt(durMatch[1], 10) : null;

  // Espaço (Gather space)
  const spaceMatch = text.match(/space[:\s]+([^\n]+)/i);
  const spaceName = spaceMatch ? spaceMatch[1].trim() : null;

  // Participantes — bloco "Attendees" / "Participants"
  const attendees = extractList(text, /(?:attendees|participants|participantes)[:\s]*\n([\s\S]*?)(?:\n\n|\n[A-Z][a-z]+:|$)/i);

  // Resumo
  const summary = extractBlock(text, /(?:summary|resumo)[:\s]*\n([\s\S]*?)(?:\n\n[A-Z]|\n(?:action items|takeaways|key takeaways|next steps|recording|transcript)|$)/i);

  // Action items
  const actionItems = extractList(text, /(?:action items|next steps|tarefas)[:\s]*\n([\s\S]*?)(?:\n\n[A-Z]|\n(?:takeaways|key takeaways|recording|transcript|summary)|$)/i);

  // Key takeaways
  const keyTakeaways = extractList(text, /(?:key takeaways|takeaways|destaques)[:\s]*\n([\s\S]*?)(?:\n\n[A-Z]|\n(?:action items|recording|transcript|summary)|$)/i);

  // Links
  const recordingUrl = (text.match(/https?:\/\/\S*(?:recording|playback|video)\S*/i) || [])[0] || null;
  const transcriptUrl = (text.match(/https?:\/\/\S*(?:transcript|transcri)\S*/i) || [])[0] || null;

  function extractBlock(src, regex) {
    const m = src.match(regex);
    return m ? m[1].trim() : null;
  }
  function extractList(src, regex) {
    const block = extractBlock(src, regex);
    if (!block) return [];
    return block
      .split('\n')
      .map((l) => l.replace(/^[\-*•·\d.\s]+/, '').trim())
      .filter(Boolean);
  }

  out.push({
    json: {
      email_id: messageId,
      thread_id: threadId,
      subject,
      from_address: typeof fromAddress === 'string' ? fromAddress : JSON.stringify(fromAddress),
      meeting_title: meetingTitle,
      meeting_date: meetingDate,
      duration_min: durationMin,
      attendees,
      summary,
      action_items: actionItems,
      key_takeaways: keyTakeaways,
      recording_url: recordingUrl,
      transcript_url: transcriptUrl,
      space_name: spaceName,
      raw_text: text.slice(0, 50000),
      raw_html: (html || '').slice(0, 50000),
      received_at: new Date().toISOString(),
      sent_to_telegram: false
    }
  });
}

return out;

// Monta a mensagem HTML para o Telegram NRO.
const MAX = 3500;
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const date = j.meeting_date ? new Date(j.meeting_date).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '—';
  const dur = j.duration_min ? `${j.duration_min} min` : '—';

  const list = (arr, max = 8) => {
    if (!arr || !arr.length) return '—';
    const a = Array.isArray(arr) ? arr : (() => { try { return JSON.parse(arr); } catch { return []; } })();
    const head = a.slice(0, max).map((x) => `• ${esc(x)}`).join('\n');
    return a.length > max ? `${head}\n• <i>(+${a.length - max})</i>` : head;
  };

  const summary = j.summary ? esc(j.summary).slice(0, 1200) : '—';

  let msg = '';
  msg += `🎙️ <b>FRC · Reunião Gather</b>\n`;
  msg += `<b>${esc(j.meeting_title || 'Sem título')}</b>\n`;
  msg += `🕒 ${esc(date)}  ·  ⏱️ ${esc(dur)}\n`;
  if (j.space_name) msg += `🏢 ${esc(j.space_name)}\n`;
  msg += `\n<b>Participantes</b>\n${list(j.attendees, 12)}\n`;
  msg += `\n<b>Resumo</b>\n${summary}\n`;
  msg += `\n<b>Action items</b>\n${list(j.action_items, 10)}\n`;
  if (j.key_takeaways && (Array.isArray(j.key_takeaways) ? j.key_takeaways.length : true)) {
    msg += `\n<b>Takeaways</b>\n${list(j.key_takeaways, 6)}\n`;
  }
  const links = [];
  if (j.recording_url) links.push(`<a href="${esc(j.recording_url)}">Gravação</a>`);
  if (j.transcript_url) links.push(`<a href="${esc(j.transcript_url)}">Transcript</a>`);
  if (links.length) msg += `\n${links.join('  ·  ')}\n`;

  if (msg.length > MAX) msg = msg.slice(0, MAX) + '\n…';

  out.push({ json: { ...j, telegram_text: msg } });
}
return out;
